L"  const condition = source.condition || {};\n"
L"  const wind = source.wind || {};\n"
L"  const direction = wind.direction || {};\n"
L"  return {\n"
L"    time: textValue(pick(source, ['obsTime', 'updateTime', 'fxTime', 'observationTime'])),\n"
L"    temp: temperatureCelsius(pick(source, ['temperature', 'temp'])),\n"
L"    feels: temperatureCelsius(pick(source, ['feelsLike', 'apparentTemperature', 'feels'])),\n"
L"    humidity: ratioPercent(pick(source, ['humidity', 'relativeHumidity'])),\n"
L"    windSpeed: windKilometersPerHour(pick(wind, ['speed'], pick(source, ['windSpeed', 'windSpeed10m']))),\n"
L"    windDir: textValue(pick(direction, ['compass'], pick(source, ['windDir', 'windDirection']))),\n"
L"    precip: precipitationMillimeters(pick(source, ['precipitation', 'precip'])),\n"
L"    pressure: measurementValue(pick(source, ['pressure'])),\n"
L"    visibility: distanceKilometers(pick(source, ['visibility', 'vis'])),\n"
L"    cloud: ratioPercent(pick(source, ['cloudCover', 'cloud'])),\n"
L"    dew: temperatureCelsius(pick(source, ['dewPoint', 'dew'])),\n"
L"    code: textValue(pick(condition, ['code'], pick(source, ['icon', 'weatherCode', 'code'], '999'))),\n"
L"    text: textValue(pick(condition, ['text'], pick(source, ['text', 'weatherText']))),\n"
L"    isDay: finiteNumber(pick(source, ['isDay']), null)\n"
L"  };\n"
L"}\n"
L"\n"
L"function normalizeQHourly(raw) {\n"
L"  const rows = Array.isArray(raw && raw.hours)\n"
L"    ? raw.hours\n"
L"    : Array.isArray(raw && raw.hourly) ? raw.hourly : [];\n"
L"  return rows.map((row) => {\n"
L"    const condition = row.condition || {};\n"
L"    const wind = row.wind || {};\n"
L"    const direction = wind.direction || {};\n"
L"    const precipitation = row.precipitation || {};\n"
L"    return {\n"
L"      time: textValue(pick(row, ['forecastTime', 'fxTime', 'time'])),\n"
L"      temp: temperatureCelsius(pick(row, ['temperature', 'temp'])),\n"
L"      feels: temperatureCelsius(pick(row, ['feelsLike', 'apparentTemperature'])),\n"
L"      humidity: ratioPercent(pick(row, ['humidity', 'relativeHumidity'])),\n"
L"      windSpeed: windKilometersPerHour(pick(wind, ['speed'], pick(row, ['windSpeed']))),\n"
L"      windDir: textValue(pick(direction, ['compass'], pick(row, ['windDir', 'windDirection']))),\n"
L"      precip: precipitationMillimeters(pick(row, ['precipitation', 'precip'])),\n"
L"      pop: ratioPercent(pick(precipitation, ['probability'], pick(row, ['pop', 'precipitationProbability']))),\n"
L"      code: textValue(pick(condition, ['code'], pick(row, ['icon', 'weatherCode', 'code'], '999'))),\n"
L"      text: textValue(pick(condition, ['text'], pick(row, ['text', 'weatherText']))),\n"
L"      isDay: finiteNumber(pick(row, ['isDay']), null)\n"
L"    };\n"
L"  });\n"
L"}\n"
L"\n"
L"function normalizeQDaily(raw) {\n"
L"  const rows = Array.isArray(raw && raw.days)\n"
L"    ? raw.days\n"
L"    : Array.isArray(raw && raw.daily) ? raw.daily : [];\n"
L"  return rows.map((row) => {\n"
L"    const daytime = row.daytime || row;\n"
L"    const condition = daytime.condition || {};\n"
L"    const precipitation = daytime.precipitation || row.precipitation || {};\n"
L"    const astro = row.astro || {};\n"
L"    const forecastStart = textValue(pick(row, ['forecastStartTime', 'fxDate', 'forecastDate', 'date']));\n"
L"    const forecastEnd = textValue(pick(row, ['forecastEndTime']));\n"
L"    const isUtcPeriod = /(?:Z|[+-]00:00)$/i.test(forecastStart);\n"
L"    const datePeriod = isUtcPeriod ? forecastEnd || forecastStart : forecastStart;\n"
L"    return {\n"
L"      date: datePeriod.includes('T') ? datePeriod.split('T')[0] : datePeriod,\n"
L"      tempMax: temperatureCelsius(pick(row, ['temperatureMax', 'tempMax', 'maxTemp'], daytime.temperatureMax)),\n"
L"      tempMin: temperatureCelsius(pick(row, ['temperatureMin', 'tempMin', 'minTemp'], daytime.temperatureMin)),\n"
L"      code: textValue(pick(condition, ['code'], pick(row, ['iconDay', 'icon', 'weatherCodeDay'], '999'))),\n"
L"      text: textValue(pick(condition, ['text'], pick(row, ['textDay', 'text', 'weatherTextDay']))),\n"
L"      pop: ratioPercent(pick(precipitation, ['probability'], pick(row, ['pop', 'precipitationProbability']))),\n"
L"      sunrise: textValue(pick(astro, ['sunrise'], pick(row, ['sunrise']))),\n"
L"      sunset: textValue(pick(astro, ['sunset'], pick(row, ['sunset'])))\n"
L"    };\n"
L"  });\n"
L"}\n"
L"\n"
L"function normalizeQMinutely(raw) {\n"
L"  const rows = Array.isArray(raw && raw.minutely) ? raw.minutely : [];\n"
L"  return {\n"
L"    available: finiteNumber(raw && raw.code, 200) !== 204,\n"
L"    summary: textValue(raw && raw.summary),\n"
L"    updated: textValue(pick(raw || {}, ['updateTime'])),\n"
L"    points: rows.map((row) => ({\n"
L"      time: textValue(pick(row, ['fxTime', 'time'])),\n"
L"      precip: finiteNumber(pick(row, ['precip', 'precipitation']), 0),\n"
L"      type: textValue(pick(row, ['type', 'precipitationType']))\n"
L"    })),\n"
L"    refer: normalizeRefer(raw)\n"
L"  };\n"
L"}\n"
L"\n"
L"function normalizeQAlerts(raw) {\n"
L"  const rows = Array.isArray(raw && raw.alerts)\n"
L"    ? raw.alerts\n"
L"    : Array.isArray(raw && raw.warning)\n"
L"      ? raw.warning\n"
L"      : Array.isArray(raw && raw.alert)\n"
L"        ? raw.alert\n"
L"        : [];\n"
L"  return {\n"
L"    items: rows.map((row) => ({\n"
L"      id: textValue(pick(row, ['id', 'warningId'])),\n"
L"      title: textValue(pick(row, ['title', 'headline', 'typeName'])),\n"
L"      sender: textValue(pick(row, ['senderName', 'sender', 'source'])),\n"
L"      published: textValue(pick(row, ['issuedTime', 'pubTime', 'publishTime', 'effectiveTime'])),\n"
L"      start: textValue(pick(row, ['onsetTime', 'effectiveTime', 'startTime', 'effective'])),\n"
L"      end: textValue(pick(row, ['expireTime', 'endTime', 'expires'])),\n"
L"      status: textValue(pick(row, ['status'])),\n"
L"      severity: textValue(pick(row, ['severity', 'level', 'severityText'])),\n"
L"      color: pick(row, ['severityColor', 'color']),\n"
L"      type: textValue(pick(row && row.eventType || {}, ['name', 'code'], pick(row, ['typeName', 'event']))),\n"
L"      description: textValue(pick(row, ['description', 'text', 'detail'])),\n"
L"      standard: textValue(pick(row, ['standard', 'criteria', 'eventDescription'])),\n"
L"      instruction: textValue(pick(row, ['instruction', 'defense', 'recommendedAction']))\n"
L"    })),\n"
L"    refer: normalizeRefer(raw)\n"
L"  };\n"
L"}\n"
L"\n"
L"function pollutantFromLegacy(source, code, label) {\n"
L"  const value = finiteNumber(source && source[code]);\n"
L"  return value === null ? null : { code, name: label, value, unit: 'ug/m3' };\n"
L"}\n"
L"\n"
L"function normalizeQAir(raw) {\n"
L"  const indexes = Array.isArray(raw && raw.indexes) ? raw.indexes : [];\n"
L"  const legacy = raw && raw.now || {};\n"
L"  const index = indexes.find((item) => /^cn-mee/i.test(textValue(item.code))) ||\n"
L"    indexes.find((item) => textValue(item.code).toLowerCase() === 'qaqi') ||\n"
L"    indexes[0] || legacy;\n"
L"  const rows = Array.isArray(raw && raw.pollutants) ? raw.pollutants : [];\n"
L"  const pollutants = rows.map((row) => {\n"
L"    const concentration = row && row.concentration || {};\n"
L"    return {\n"
L"      code: textValue(pick(row, ['code', 'name'])).toLowerCase(),\n"
L"      name: textValue(pick(row, ['name', 'fullName', 'code'])),\n"
L"      value: finiteNumber(pick(concentration, ['value'], pick(row, ['value', 'concentration']))),\n"
L"      unit: textValue(pick(concentration, ['unit'], pick(row, ['unit'], 'ug/m3')))\n"
L"    };\n"
L"  }).filter((item) => item.value !== null);\n"
L"  if (!pollutants.length && legacy) {\n"
L"    for (const item of [\n"
L"      pollutantFromLegacy(legacy, 'pm2p5', 'PM2.5'),\n"
L"      pollutantFromLegacy(legacy, 'pm10', 'PM10'),\n"
L"      pollutantFromLegacy(legacy, 'o3', 'O3'),\n"
L"      pollutantFromLegacy(legacy, 'no2', 'NO2'),\n"
L"      pollutantFromLegacy(legacy, 'so2', 'SO2'),\n"
L"      pollutantFromLegacy(legacy, 'co', 'CO')\n"
L"    ]) if (item) pollutants.push(item);\n"
L"  }\n"
L"  const health = index && index.health || {};\n"
L"  const advice = health && health.advice || {};\n"
L"  return {\n"
L"    aqi: finiteNumber(pick(index, ['aqi', 'aqiDisplay'])),\n"
L"    category: textValue(pick(index, ['category', 'levelName'])),\n"
L"    level: textValue(pick(index, ['level'])),\n"
L"    primary: textValue(pick(index && index.primaryPollutant || {}, ['name', 'fullName', 'code'], pick(index, ['primary']))),\n"
L"    advice: textValue(pick(advice, ['generalPopulation'], pick(health, ['effect'], pick(index, ['healthAdvice'])))),\n"
L"    pollutants,\n"
L"    refer: normalizeRefer(raw)\n"
L"  };\n"
L"}\n"
L"\n"
L"const Q_NORMALIZERS = Object.freeze({\n"
L"  current: normalizeQCurrent,\n"
L"  minutely: normalizeQMinutely,\n"
L"  alerts: normalizeQAlerts,\n"
L"  hourly: normalizeQHourly,\n"
L"  daily: normalizeQDaily,\n"
L"  air: normalizeQAir\n"
L"});\n"
L"\n"
L"function qDatasetUrl(name) {\n"
L"  const lat = state.coords.lat.toFixed(2);\n"
L"  const lon = state.coords.lon.toFixed(2);\n"
L"  const common = { lang: apiLanguage(), localTime: 'true' };\n"
L"  switch (name) {\n"
L"    case 'current':\n"
L"      return qweatherUrl(`/weather/v1/current/${lat}/${lon}`, common);\n"
L"    case 'hourly':\n"
L"      return qweatherUrl(`/weather/v1/hourly/${lat}/${lon}`, { ...common, hours: 24 });\n"
L"    case 'daily':\n"
L"      return qweatherUrl(`/weather/v1/daily/${lat}/${lon}`, { ...common, days: 5 });\n"
L"    case 'minutely':\n"
L"      return qweatherUrl('/v7/minutely/5m', { lang: apiLanguage(), location: `${lon},${lat}` });\n"
L"    case 'alerts':\n"
L"      return qweatherUrl(`/weatheralert/v1/current/${lat}/${lon}`, { lang: apiLanguage() });\n"
L"    case 'air':\n"
L"      return qweatherUrl(`/airquality/v1/current/${lat}/${lon}`, { lang: apiLanguage() });\n"
L"    default:\n"
L"      throw new Error(`Unknown QWeather dataset: ${name}`);\n"
L"  }\n"
L"}\n"
L"\n"
L"function recordQWeatherFailure(name, error) {\n"
L"  const now = Date.now();\n"
L"  const status = Number(error && error.status) || 0;\n"
L"  const failureCount = Math.min(8, (state.failureCounts[name] || 0) + 1);\n"
L"  state.failureCounts[name] = failureCount;\n"
L"  state.errors[name] = error && error.message || String(error);\n"
L"  if (status === 401 || status === 403) {\n"
L"    state.qAuthFailed = true;\n"
L"    for (const datasetName of DATASET_NAMES) state.nextDue[datasetName] = Number.POSITIVE_INFINITY;\n"
L"  } else if (status === 429) {\n"
L"    state.qBackoffUntil = now + Math.max(RATE_LIMIT_BACKOFF, Number(error.retryAfterMs) || 0);\n"
L"    state.nextDue[name] = state.qBackoffUntil;\n"
L"  } else if (status >= 400 && status < 500 && status !== 408) {\n"
L"    state.nextDue[name] = now + Math.max(DATASET_TTL[name], 60 * 60 * 1000);\n"
L"  } else {\n"
L"    const maximumDelay = Math.max(DATASET_TTL[name], 30 * 60 * 1000);\n"
L"    state.nextDue[name] = now + Math.min(maximumDelay, FAILURE_RETRY_DELAY * (2 ** (failureCount - 1)));\n"
L"  }\n"
L"}\n"
L"\n"
L"async function fetchQDataset(name, force, generation) {\n"
L"  const now = Date.now();\n"
L"  if (generation !== state.generation || state.qAuthFailed || state.inFlight[name]) return null;\n"
L"  if (!force && (now < (state.nextDue[name] || 0) || now < state.qBackoffUntil)) return null;\n"
L"  state.inFlight[name] = true;\n"
L"  try {\n"
L"    const raw = qweatherResponse(await getJson(qDatasetUrl(name)));\n"
L"    if (generation !== state.generation) return null;\n"
L"    const normalized = Q_NORMALIZERS[name](raw);\n"
L"    state.datasets[name] = { data: normalized, fetchedAt: Date.now(), refer: normalizeRefer(raw) };\n"
L"    state.nextDue[name] = Date.now() + DATASET_TTL[name];\n"
L"    delete state.failureCounts[name];\n"
L"    if (finiteNumber(raw && raw.code, 200) === 204 && name !== 'alerts') {\n"
L"      state.errors[name] = 'QWeather 204';\n"
L"    } else {\n"
L"      delete state.errors[name];\n"
L"    }\n"
L"    if (name === 'current' && normalized && normalized.temp !== null) {\n"
L"      state.mode = 'qweather';\n"
L"      state.status = 'ready';\n"
L"    }\n"
L"    scheduleRenderAndCapture(name === 'current');\n"
L"    return normalized;\n"
L"  } catch (error) {\n"
L"    if (generation === state.generation) recordQWeatherFailure(name, error);\n"
L"    throw error;\n"
L"  } finally {\n"
L"    if (generation === state.generation) delete state.inFlight[name];\n"
L"  }\n"
L"}\n"
L"\n"
L"async function refreshQWeather(force, generation) {\n"
L"  if (!state.apiHost || !state.coords || state.qAuthFailed || generation !== state.generation) return;\n"
L"  await Promise.allSettled(DATASET_NAMES.map((name) => fetchQDataset(name, force, generation)));\n"
L"}\n"
L"\n"
L"async function resolveQWeatherLocation(query, generation) {\n"
L"  const raw = qweatherResponse(await getJson(qweatherUrl('/geo/v2/city/lookup', {\n"
L"    location: query,\n"
L"    number: 1,\n"
L"    lang: apiLanguage()\n"
L"  })));\n"
L"  if (generation !== state.generation) throw new Error('Superseded location request');\n"
L"  const row = Array.isArray(raw.location) ? raw.location[0] : null;\n"
L"  const lat = finiteNumber(row && row.lat);\n"
L"  const lon = finiteNumber(row && row.lon);\n"
L"  if (lat === null || lon === null) throw new Error('QWeather location not found');\n"
L"  return {\n"
L"    lat,\n"
L"    lon,\n"
L"    name: textValue(row.name),\n"
L"    city: textValue(pick(row, ['adm2', 'adm1'])),\n"
L"    country: textValue(row.country),\n"
L"    source: 'QWeather'\n"
L"  };\n"
L"}\n"
L"\n"
L"async function resolveFallbackLocation(query, generation) {\n"
L"  let lastError = null;\n"
L"  try {\n"
L"    const url = `https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates?SingleLine=${encodeURIComponent(query)}&f=json&maxLocations=1&outFields=*`;\n"
L"    const raw = await getJson(url);\n"
L"    const candidate = raw && raw.candidates && raw.candidates[0];\n"
L"    const attributes = candidate && candidate.attributes || {};\n"
L"    const lat = finiteNumber(candidate && candidate.location && candidate.location.y);\n"
L"    const lon = finiteNumber(candidate && candidate.location && candidate.location.x);\n"
L"    if (lat !== null && lon !== null) {\n"
L"      return {\n"
L"        lat,\n"
L"        lon,\n"
L"        name: textValue(pick(attributes, ['ShortLabel', 'PlaceName'])),\n"
L"        city: textValue(pick(attributes, ['City', 'Subregion'])),\n"
L"        country: textValue(attributes.Country),\n"
L"        source: 'Esri'\n"
L"      };\n"
L"    }\n"
L"  } catch (error) {\n"
L"    lastError = error;\n"
L"  }\n"
L"  try {\n"
L"    const raw = await getJson(`https://photon.komoot.io/api/?q=${encodeURIComponent(query)}&limit=1`);\n"
L"    const feature = raw && raw.features && raw.features[0];\n"
L"    const coordinates = feature && feature.geometry && feature.geometry.coordinates || [];\n"
L"    const properties = feature && feature.properties || {};\n"
L"    const lat = finiteNumber(coordinates[1]);\n"
L"    const lon = finiteNumber(coordinates[0]);\n"
L"    if (generation === state.generation && lat !== null && lon !== null) {\n"
L"      return {\n"
L"        lat,\n"
L"        lon,\n"
L"        name: textValue(pick(properties, ['name', 'district'])),\n"
L"        city: textValue(pick(properties, ['city', 'county', 'state'])),\n"
L"        country: textValue(properties.country),\n"
L"        source: 'Photon'\n"
L"      };\n"
L"    }\n"
L"  } catch (error) {\n"
L"    lastError = error;\n"
L"  }\n"
L"  throw lastError || new Error('Location not found');\n"
L"}\n"
L"\n"
L"async function resolveLocation(generation) {\n"
L"  if (state.apiHost && !state.qAuthFailed) {\n"
L"    try {\n"
L"      return await resolveQWeatherLocation(state.location, generation);\n"
L"    } catch (error) {\n"
L"      const status = Number(error && error.status) || 0;\n"
L"      if (status === 401 || status === 403) state.qAuthFailed = true;\n"
L"    }\n"
L"  }\n"
L"  return resolveFallbackLocation(state.location, generation);\n"
L"}\n"
L"\n"
L"function normalizeOpenMeteo(raw) {\n"
L"  const current = raw && raw.current || {};\n"
L"  const hourly = raw && raw.hourly || {};\n"
L"  const daily = raw && raw.daily || {};\n"
L"  const currentData = {\n"
L"    time: textValue(current.time),\n"
L"    temp: finiteNumber(current.temperature_2m),\n"
L"    feels: finiteNumber(current.apparent_temperature),\n"
L"    humidity: finiteNumber(current.relative_humidity_2m),\n"
L"    windSpeed: finiteNumber(current.wind_speed_10m),\n"
L"    windDir: '',\n"
L"    precip: finiteNumber(current.precipitation),\n"
L"    pressure: finiteNumber(current.surface_pressure),\n"
L"    visibility: finiteNumber(current.visibility) === null ? null : finiteNumber(current.visibility) / 1000,\n"
L"    cloud: finiteNumber(current.cloud_cover),\n"
L"    dew: finiteNumber(current.dew_point_2m),\n"
L"    code: textValue(current.weather_code, '999'),\n"
L"    text: '',\n"
L"    isDay: finiteNumber(current.is_day, 1)\n"
L"  };\n"
L"  const hourlyRows = Array.isArray(hourly.time) ? hourly.time.map((time, index) => ({\n"
L"    time: textValue(time),\n"
L"    temp: finiteNumber(hourly.temperature_2m && hourly.temperature_2m[index]),\n"
L"    feels: finiteNumber(hourly.apparent_temperature && hourly.apparent_temperature[index]),\n"
L"    humidity: finiteNumber(hourly.relative_humidity_2m && hourly.relative_humidity_2m[index]),\n"
L"    windSpeed: finiteNumber(hourly.wind_speed_10m && hourly.wind_speed_10m[index]),\n"
L"    precip: finiteNumber(hourly.precipitation && hourly.precipitation[index]),\n"
L"    pop: clampPercent(hourly.precipitation_probability && hourly.precipitation_probability[index]),\n"
L"    code: textValue(hourly.weather_code && hourly.weather_code[index], '999'),\n"
L"    text: '',\n"
L"    isDay: finiteNumber(hourly.is_day && hourly.is_day[index], 1)\n"
L"  })) : [];\n"
L"  const dailyRows = Array.isArray(daily.time) ? daily.time.map((date, index) => ({\n"
L"    date: textValue(date),\n"
L"    tempMax: finiteNumber(daily.temperature_2m_max && daily.temperature_2m_max[index]),\n"
L"    tempMin: finiteNumber(daily.temperature_2m_min && daily.temperature_2m_min[index]),\n"
L"    code: textValue(daily.weather_code && daily.weather_code[index], '999'),\n"
L"    text: '',\n"
L"    pop: clampPercent(daily.precipitation_probability_max && daily.precipitation_probability_max[index])\n"
L"  })) : [];\n"
L"  return { current: currentData, hourly: hourlyRows, daily: dailyRows };\n"
L"}\n"
L"\n"
L"async function refreshFallback(force, generation) {\n"
L"  const now = Date.now();\n"
L"  if (!state.coords || generation !== state.generation || state.inFlight.fallback) return;\n"
L"  if (!force && now < state.fallbackDue) return;\n"
L"  state.inFlight.fallback = true;\n"
L"  try {\n"
L"    const lat = state.coords.lat.toFixed(5);\n"
L"    const lon = state.coords.lon.toFixed(5);\n"
L"    const url = `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current=temperature_2m,apparent_temperature,relative_humidity_2m,weather_code,is_day,wind_speed_10m,precipitation,surface_pressure,visibility,cloud_cover,dew_point_2m&hourly=temperature_2m,apparent_temperature,relative_humidity_2m,precipitation_probability,precipitation,weather_code,is_day,wind_speed_10m&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max&timezone=auto&forecast_days=5&wind_speed_unit=kmh`;\n"
L"    const normalized = normalizeOpenMeteo(await getJson(url));\n"
L"    if (generation !== state.generation) return;\n"
L"    state.fallback = { data: normalized, fetchedAt: Date.now() };\n"
L"    state.fallbackDue = Date.now() + FALLBACK_TTL;\n"
L"    state.fallbackFailureCount = 0;\n"
L"    delete state.errors.fallback;\n"
L"    if (!state.datasets.current || state.datasets.current.data.temp === null) {\n"
L"      state.mode = 'open-meteo';\n"
L"      state.status = 'ready';\n"
L"    }\n"
L"    scheduleRenderAndCapture(true);\n"
L"  } catch (error) {\n"
L"    if (generation === state.generation) {\n"
L"      state.errors.fallback = error && error.message || String(error);\n"
L"      state.fallbackFailureCount = Math.min(8, state.fallbackFailureCount + 1);\n"
L"      state.fallbackDue = Date.now() + Math.min(\n"
L"        30 * 60 * 1000,\n"
L"        FAILURE_RETRY_DELAY * (2 ** (state.fallbackFailureCount - 1))\n"
L"      );\n"
L"    }\n"
L"    throw error;\n"
L"  } finally {\n"
L"    if (generation === state.generation) delete state.inFlight.fallback;\n"
L"  }\n"
L"}\n"
L"\n"
L"async function refreshDue(force, generation = state.generation) {\n"
L"  if (generation !== state.generation || !state.coords) return;\n"
L"  if (state.apiHost && !state.qAuthFailed) await refreshQWeather(force, generation);\n"
L"  const hasQCurrent = state.datasets.current && state.datasets.current.data.temp !== null;\n"
L"  if (!hasQCurrent) {\n"
L"    try {\n"
L"      await refreshFallback(force, generation);\n"
L"    } catch (error) {\n"
L"      // Keep the last valid data and the bounded retry schedule.\n"
L"    }\n"
L"  }\n"
L"  if (generation === state.generation) {\n"
L"    renderWeather();\n"
L"    if (hasCurrentData()) state.status = 'ready';\n"
L"  }\n"
L"}\n"
L"\n"
L"async function initializeWeather(generation) {\n"
L"  state.status = 'loading';\n"
L"  setLoading();\n"
L"  try {\n"
L"    const place = await resolveLocation(generation);\n"
L"    if (generation !== state.generation) return;\n"
L"    state.coords = { lat: place.lat, lon: place.lon };\n"
L"    state.place = place;\n"
L"    await refreshDue(true, generation);\n"
L"    if (generation === state.generation && !hasCurrentData()) throw new Error('Weather data unavailable');\n"
L"  } catch (error) {\n"
L"    if (generation !== state.generation) return;\n"
L"    state.errors.initialization = error && error.message || String(error);\n"
L"    state.status = hasCurrentData() ? 'ready' : 'error';\n"
L"    if (state.status === 'error') setError();\n"
L"  }\n"
L"}\n"
L"\n"
L"function resetState() {\n"
L"  ++state.generation;\n"
L"  state.status = 'idle';\n"
L"  state.mode = 'none';\n"
L"  state.coords = null;\n"
L"  state.place = null;\n"
L"  state.datasets = Object.create(null);\n"
L"  state.fallback = null;\n"
L"  state.nextDue = Object.create(null);\n"
L"  state.inFlight = Object.create(null);\n"
L"  state.errors = Object.create(null);\n"
L"  state.failureCounts = Object.create(null);\n"
L"  state.fallbackDue = 0;\n"
L"  state.fallbackFailureCount = 0;\n"
L"  state.qAuthFailed = false;\n"
L"  state.qBackoffUntil = 0;\n"
L"  if (state.refreshTimer) clearInterval(state.refreshTimer);\n"
L"  state.refreshTimer = setInterval(() => {\n"
L"    refreshDue(false).catch(() => {});\n"
L"  }, 60 * 1000);\n"
L"}\n"
L"const elements = {\n"
L"  weather: document.getElementById('weather'),\n"
L"  location: document.getElementById('location'),\n"
L"  resolved: document.getElementById('resolved'),\n"
L"  providerState: document.getElementById('provider-state'),\n"
L"  alerts: document.getElementById('alerts'),\n"
L"  currentIcon: document.getElementById('current-icon'),\n"
L"  temperature: document.getElementById('temperature'),\n"
L"  unit: document.getElementById('unit'),\n"
L"  condition: document.getElementById('condition'),\n"
L"  updated: document.getElementById('updated'),\n"
L"  feels: document.getElementById('feels'),\n"
L"  humidity: document.getElementById('humidity'),\n"
L"  wind: document.getElementById('wind'),\n"
L"  precip: document.getElementById('precip'),\n"
L"  visibility: document.getElementById('visibility'),\n"
L"  minuteSection: document.getElementById('minute-section'),\n"
L"  minuteUpdated: document.getElementById('minute-updated'),\n"
L"  minuteSummary: document.getElementById('minute-summary'),\n"
L"  minuteChart: document.getElementById('minute-chart'),\n"
L"  minuteAxis: document.getElementById('minute-axis'),\n"
L"  hourly: document.getElementById('hourly'),\n"
L"  hourlyNote: document.getElementById('hourly-note'),\n"
L"  airSection: document.getElementById('air-section'),\n"
L"  airNote: document.getElementById('air-note'),\n"
L"  aqiValue: document.getElementById('aqi-value'),\n"
L"  aqiCategory: document.getElementById('aqi-category'),\n"
L"  pollutants: document.getElementById('pollutants'),\n"
L"  airAdvice: document.getElementById('air-advice'),\n"
L"  forecast: document.getElementById('forecast'),\n"
L"  dailyNote: document.getElementById('daily-note'),\n"
L"  poweredBy: document.getElementById('powered-by'),\n"
L"  sourceList: document.getElementById('source-list')\n"
L"};\n"
L"\n"
L"let renderTimer = null;\n"
L"\n"
L"function isChinese() {\n"
L"  return /^zh/i.test(state.language || '');\n"
L"}\n"
L"\n"
L"function labels() {\n"
L"  return isChinese() ? {\n"
L"    loading: '\\u52a0\\u8f7d\\u4e2d...',\n"
L"    error: '\\u65e0\\u6cd5\\u83b7\\u53d6\\u5929\\u6c14',\n"
L"    feels: '\\u4f53\\u611f',\n"
L"    humidity: '\\u6e7f\\u5ea6',\n"
L"    wind: '\\u98ce\\u901f',\n"
L"    precip: '\\u964d\\u6c34',\n"
L"    visibility: '\\u80fd\\u89c1\\u5ea6',\n"
L"    updated: '\\u66f4\\u65b0',\n"
L"    next2h: '\\u672a\\u6765 2 \\u5c0f\\u65f6\\u964d\\u6c34',\n"
L"    hourly24: '\\u672a\\u6765 24 \\u5c0f\\u65f6',\n"
L"    rainChance: '\\u964d\\u96e8\\u6982\\u7387',\n"
L"    air: '\\u7a7a\\u6c14\\u8d28\\u91cf',\n"
L"    daily5: '\\u672a\\u6765 5 \\u5929',\n"
L"    today: '\\u4eca\\u5929',\n"
L"    now: '\\u73b0\\u5728',\n"
L"    unavailable: '\\u6570\\u636e\\u6682\\u4e0d\\u53ef\\u7528',\n"
L"    fallback: 'Open-Meteo \\u56de\\u9000',\n"
L"    authFailed: '\\u548c\\u98ce\\u5929\\u6c14\\u8ba4\\u8bc1\\u5931\\u8d25',\n"
L"    lastData: '\\u663e\\u793a\\u6700\\u8fd1\\u6570\\u636e',\n"
L"    partial: '\\u90e8\\u5206\\u6570\\u636e\\u6682\\u4e0d\\u53ef\\u7528',\n"
L"    powered: '\\u5929\\u6c14\\u670d\\u52a1\\u7531\\u548c\\u98ce\\u5929\\u6c14\\u9a71\\u52a8',\n"
L"    sources: '\\u6570\\u636e\\u6e90',\n"
L"    publisher: '\\u53d1\\u5e03\\u673a\\u6784',\n"
L"    validUntil: '\\u6709\\u6548\\u671f',\n"
L"    standard: '\\u9884\\u8b66\\u6807\\u51c6',\n"
L"    details: '\\u9884\\u8b66\\u6b63\\u6587',\n"
L"    instruction: '\\u9632\\u5fa1\\u6307\\u5357',\n"
L"    officialAlert: '\\u5b98\\u65b9\\u9884\\u8b66',\n"
L"    noRain: '\\u672a\\u6765 2 \\u5c0f\\u65f6\\u6682\\u65e0\\u660e\\u663e\\u964d\\u6c34',\n"
L"    minutePoints: '\\u6bcf 5 \\u5206\\u949f',\n"
L"    qweather: '\\u548c\\u98ce\\u5929\\u6c14'\n"
L"  } : {\n"
L"    loading: 'Loading...',\n"
L"    error: 'Unable to load weather',\n"
L"    feels: 'Feels like',\n"
L"    humidity: 'Humidity',\n"
L"    wind: 'Wind',\n"
L"    precip: 'Precipitation',\n"
L"    visibility: 'Visibility',\n"
L"    updated: 'Updated',\n"
L"    next2h: 'Precipitation in the next 2 hours',\n"
L"    hourly24: 'Next 24 hours',\n"
L"    rainChance: 'Rain chance',\n"
L"    air: 'Air quality',\n"
L"    daily5: 'Next 5 days',\n"
L"    today: 'Today',\n"
L"    now: 'Now',\n"
L"    unavailable: 'Data temporarily unavailable',\n"
L"    fallback: 'Open-Meteo fallback',\n"
L"    authFailed: 'QWeather authentication failed',\n"
L"    lastData: 'Showing last data',\n"
L"    partial: 'Some data is temporarily unavailable',\n"
L"    powered: 'Weather data powered by QWeather',\n"
L"    sources: 'Sources',\n"
L"    publisher: 'Publisher',\n"
L"    validUntil: 'Valid period',\n"
L"    standard: 'Alert standard',\n"
L"    details: 'Alert details',\n"
L"    instruction: 'Safety guidance',\n"
L"    officialAlert: 'Official alert',\n"
L"    noRain: 'No significant precipitation in the next 2 hours',\n"
L"    minutePoints: 'Every 5 minutes',\n"
L"    qweather: 'QWeather'\n"
L"  };\n"
L"}\n"
L"\n"
L"function setStaticLabels() {\n"
L"  const value = labels();\n"
L"  document.getElementById('feels-label').textContent = value.feels;\n"
L"  document.getElementById('humidity-label').textContent = value.humidity;\n"
L"  document.getElementById('wind-label').textContent = value.wind;\n"
L"  document.getElementById('precip-label').textContent = value.precip;\n"
L"  document.getElementById('visibility-label').textContent = value.visibility;\n"
L"  document.getElementById('minute-title').textContent = value.next2h;\n"
L"  document.getElementById('hourly-title').textContent = value.hourly24;\n"
L"  document.getElementById('air-title').textContent = value.air;\n"
L"  document.getElementById('daily-title').textContent = value.daily5;\n"
L"}\n"
L"\n"
L"function openMeteoCondition(code) {\n"
L"  const zh = isChinese();\n"
L"  const map = zh ? {\n"
L"    0: '\\u6674', 1: '\\u5927\\u90e8\\u6674\\u6717', 2: '\\u591a\\u4e91', 3: '\\u9634',\n"
L"    45: '\\u96fe', 48: '\\u51bb\\u96fe', 51: '\\u5c0f\\u96e8', 53: '\\u5c0f\\u96e8', 55: '\\u4e2d\\u96e8',\n"
L"    56: '\\u51bb\\u96e8', 57: '\\u51bb\\u96e8', 61: '\\u5c0f\\u96e8', 63: '\\u4e2d\\u96e8',\n"
L"    65: '\\u5927\\u96e8', 66: '\\u51bb\\u96e8', 67: '\\u51bb\\u96e8', 71: '\\u5c0f\\u96ea',\n"
L"    73: '\\u4e2d\\u96ea', 75: '\\u5927\\u96ea', 77: '\\u96ea\\u7c92', 80: '\\u9635\\u96e8',\n"
L"    81: '\\u9635\\u96e8', 82: '\\u5f3a\\u9635\\u96e8', 85: '\\u9635\\u96ea', 86: '\\u5f3a\\u9635\\u96ea',\n"
L"    95: '\\u96f7\\u96e8', 96: '\\u96f7\\u96e8\\u4f34\\u51b0\\u96f9', 99: '\\u96f7\\u96e8\\u4f34\\u51b0\\u96f9'\n"
L"  } : {\n"
L"    0: 'Clear', 1: 'Mainly clear', 2: 'Partly cloudy', 3: 'Overcast', 45: 'Fog',\n"
L"    48: 'Freezing fog', 51: 'Drizzle', 53: 'Drizzle', 55: 'Rain', 56: 'Freezing drizzle',\n"
L"    57: 'Freezing drizzle', 61: 'Light rain', 63: 'Rain', 65: 'Heavy rain', 66: 'Freezing rain',\n"
L"    67: 'Freezing rain', 71: 'Light snow', 73: 'Snow', 75: 'Heavy snow', 77: 'Snow grains',\n"
L"    80: 'Rain showers', 81: 'Rain showers', 82: 'Heavy rain showers', 85: 'Snow showers',\n"
L"    86: 'Heavy snow showers', 95: 'Thunderstorm', 96: 'Thunderstorm with hail', 99: 'Thunderstorm with hail'\n"
L"  };\n"
L"  return map[Number(code)] || (zh ? '\\u672a\\u77e5\\u5929\\u6c14' : 'Unknown weather');\n"
L"}\n"
L"\n"
L"function weatherText(item, provider) {\n"
L"  return textValue(item && item.text) || (provider === 'qweather'\n"
L"    ? (isChinese() ? '\\u672a\\u77e5\\u5929\\u6c14' : 'Unknown weather')\n"
L"    : openMeteoCondition(item && item.code));\n"
L"}\n"
L"\n"
L"function weatherKind(code, provider) {\n"
L"  const value = Number(code);\n"
L"  if (provider === 'qweather') {\n"
L"    if ([100, 150].includes(value)) return 'clear';\n"
L"    if ([101, 102, 151, 152].includes(value)) return 'partly';\n"
L"    if ([103, 104, 153, 154].includes(value)) return 'cloud';\n"
L"    if ((value >= 302 && value <= 304) || (value >= 307 && value <= 313)) return 'storm';\n"
L"    if (value >= 300 && value < 400) return 'rain';\n"
L"    if (value >= 400 && value < 500) return 'snow';\n"
L"    if (value >= 500 && value < 600) return 'fog';\n"
L"    return 'cloud';\n"
L"  }\n"
L"  if (value === 0 || value === 1) return 'clear';\n"
L"  if (value === 2) return 'partly';\n"
L"  if (value === 45 || value === 48) return 'fog';\n"
L"  if ((value >= 71 && value <= 77) || value === 85 || value === 86) return 'snow';\n"
L"  if (value >= 95) return 'storm';\n"
L"  if ((value >= 51 && value <= 67) || (value >= 80 && value <= 82)) return 'rain';\n"
L"  return 'cloud';\n"
L"}\n"
L"\n"
L"function isDaytime(item, provider) {\n"
L"  if (item && item.isDay !== null && item.isDay !== undefined) return Number(item.isDay) === 1;\n"
L"  const code = Number(item && item.code);\n"
L"  if (provider === 'qweather' && code >= 150 && code < 200) return false;\n"
L"  return true;\n"
L"}\n"
L"\n"
L"function drawWeatherIcon(canvas, item, provider) {\n"
L"  const context = canvas.getContext('2d');\n"
L"  const scale = canvas.width / 96;\n"
L"  const kind = weatherKind(item && item.code, provider);\n"
L"  const day = isDaytime(item, provider);\n"
L"  context.clearRect(0, 0, canvas.width, canvas.height);\n"
L"  context.save();\n"
L"  context.scale(scale, scale);\n"
L"  const sunColor = day ? '#f5b521' : '#9daed5';\n"
L"  const cloudColor = day ? '#778597' : '#8d99aa';\n"
L"  const rainColor = '#3f8bc9';\n"
L"  function sun() {\n"
L"    context.fillStyle = sunColor;\n"
L"    context.beginPath(); context.arc(40, 38, 18, 0, Math.PI * 2); context.fill();\n"
L"    context.strokeStyle = sunColor; context.lineWidth = 4;\n"
L"    for (let index = 0; index < 8; ++index) {\n"
L"      const angle = index * Math.PI / 4;\n"
L"      context.beginPath();\n"
L"      context.moveTo(40 + 23 * Math.cos(angle), 38 + 23 * Math.sin(angle));\n"
L"      context.lineTo(40 + 30 * Math.cos(angle), 38 + 30 * Math.sin(angle));\n"
L"      context.stroke();\n"
L"    }\n"
L"  }\n"
L"  function moon() {\n"
L"    context.fillStyle = sunColor;\n"
L"    context.beginPath(); context.arc(46, 43, 28, 0, Math.PI * 2); context.fill();\n"
L"    context.globalCompositeOperation = 'destination-out';\n"
L"    context.beginPath(); context.arc(60, 32, 27, 0, Math.PI * 2); context.fill();\n"
L"    context.globalCompositeOperation = 'source-over';\n"
L"  }\n"
L"  function cloud() {\n"
L"    context.fillStyle = cloudColor;\n"
L"    context.beginPath();\n"
L"    context.arc(31, 58, 21, 0, Math.PI * 2);\n"
L"    context.arc(53, 46, 27, 0, Math.PI * 2);\n"
L"    context.arc(75, 58, 19, 0, Math.PI * 2);\n"
L"    context.rect(18, 55, 75, 27);\n"
L"    context.fill();\n"
L"  }\n"
L"  function rain() {\n"
L"    context.strokeStyle = rainColor; context.lineWidth = 4; context.lineCap = 'round';\n"
L"    for (let x = 30; x <= 78; x += 16) {\n"
L"      context.beginPath(); context.moveTo(x, 79); context.lineTo(x - 6, 94); context.stroke();\n"
L"    }\n"
L"  }\n"
L"  function snow() {\n"
L"    context.strokeStyle = '#74a9d8'; context.lineWidth = 3; context.lineCap = 'round';\n"
L"    for (let x = 34; x <= 78; x += 22) {\n"
L"      for (let index = 0; index < 3; ++index) {\n"
L"        const angle = index * Math.PI / 3;\n"
L"        context.beginPath();\n"
L"        context.moveTo(x - 7 * Math.cos(angle), 84 - 7 * Math.sin(angle));\n"
L"        context.lineTo(x + 7 * Math.cos(angle), 84 + 7 * Math.sin(angle));\n"
L"        context.stroke();\n"
L"      }\n"
L"    }\n"
L"  }\n"
L"  function fog() {\n"
L"    context.strokeStyle = '#8492a3'; context.lineWidth = 4; context.lineCap = 'round';\n"
L"    for (let y = 39; y <= 81; y += 14) {\n"
L"      context.beginPath(); context.moveTo(12 + (y % 2) * 7, y); context.lineTo(86, y); context.stroke();\n"
L"    }\n"
L"  }\n"
L"  if (kind === 'clear') day ? sun() : moon();\n"
L"  else if (kind === 'partly') { day ? sun() : moon(); cloud(); }\n"
L"  else if (kind === 'fog') fog();\n"
L"  else {\n"
L"    cloud();\n"
L"    if (kind === 'snow') snow();\n"
L"    else if (kind === 'rain' || kind === 'storm') rain();\n"
L"  }\n"
L"  if (kind === 'storm') {\n"
L"    context.fillStyle = '#f5b521';\n"
L"    context.beginPath();\n"
L"    context.moveTo(57, 61); context.lineTo(42, 82); context.lineTo(54, 82);\n"
L"    context.lineTo(46, 97); context.lineTo(74, 68); context.lineTo(61, 68);\n"
L"    context.closePath(); context.fill();\n"
L"  }\n"
L"  context.restore();\n"
L"}\n"
L"\n"
L"function formatTime(value, withDate = false) {\n"
L"  if (!value) return '';\n"
L"  try {\n"
L"    const options = withDate\n"
L"      ? { month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit' }\n"
L"      : { hour: '2-digit', minute: '2-digit' };\n"
L"    return new Intl.DateTimeFormat(state.language || 'en-US', options).format(new Date(value));\n"
L"  } catch (error) {\n"
L"    const match = textValue(value).match(/(?:T|\\s)([0-9]{2}:[0-9]{2})/);\n"
L"    return match ? match[1] : textValue(value);\n"
L"  }\n"
L"}\n"
L"\n"
L"function tempUnit() {\n"
L"  return `${String.fromCharCode(176)}${state.unit ? 'F' : 'C'}`;\n"
L"}\n"
L"\n"
L"function displayTemperatureValue(value) {\n"
L"  if (value === null || value === undefined || !Number.isFinite(Number(value))) return null;\n"
L"  const celsius = Number(value);\n"
L"  return state.unit ? celsius * 9 / 5 + 32 : celsius;\n"
L"}\n"
L"\n"
L"function formatTemperature(value) {\n"
L"  const display = displayTemperatureValue(value);\n"
L"  return display === null ? '--' : `${Math.round(display)}${tempUnit()}`;\n"
L"}\n"
L"\n"
L"function formatNumber(value, suffix, digits = 0) {\n"
L"  if (value === null || value === undefined || !Number.isFinite(Number(value))) return '--';\n"
L"  return `${Number(value).toFixed(digits)}${suffix || ''}`;\n"
L"}\n"
L"\n"
L"function formatWindDirection(value) {\n"
L"  const direction = textValue(value);\n"
L"  if (!isChinese()) return direction.toUpperCase();\n"
L"  const names = {\n"
L"    n: '\\u5317\\u98ce', nne: '\\u5317\\u4e1c\\u5317\\u98ce', ne: '\\u4e1c\\u5317\\u98ce', ene: '\\u4e1c\\u4e1c\\u5317\\u98ce',\n"
L"    e: '\\u4e1c\\u98ce', ese: '\\u4e1c\\u4e1c\\u5357\\u98ce', se: '\\u4e1c\\u5357\\u98ce', sse: '\\u5357\\u4e1c\\u5357\\u98ce',\n"
L"    s: '\\u5357\\u98ce', ssw: '\\u5357\\u897f\\u5357\\u98ce', sw: '\\u897f\\u5357\\u98ce', wsw: '\\u897f\\u897f\\u5357\\u98ce',\n"
L"    w: '\\u897f\\u98ce', wnw: '\\u897f\\u897f\\u5317\\u98ce', nw: '\\u897f\\u5317\\u98ce', nnw: '\\u5317\\u897f\\u5317\\u98ce',\n"
L"    none: '\\u65e0\\u6301\\u7eed\\u98ce\\u5411', vrb: '\\u98ce\\u5411\\u4e0d\\u5b9a'\n"
L"  };\n"
L"  return names[direction.toLowerCase()] || direction;\n"
L"}\n"
L"\n"
L"function currentSource() {\n"
L"  const qDataset = state.datasets.current;\n"
L"  const qCurrent = qDataset && qDataset.data;\n"
L"  if (qCurrent && qCurrent.temp !== null) {\n"
L"    return { item: qCurrent, provider: 'qweather', fetchedAt: qDataset.fetchedAt };\n"
L"  }\n"
L"  const fallback = state.fallback && state.fallback.data && state.fallback.data.current;\n"
L"  return fallback && fallback.temp !== null\n"
L"    ? { item: fallback, provider: 'open-meteo', fetchedAt: state.fallback.fetchedAt }\n"
L"    : null;\n"
L"}\n"
L"\n"
L"function hourlySource() {\n"
L"  if (state.mode === 'qweather') {\n"
L"    return { rows: state.datasets.hourly && state.datasets.hourly.data || [], provider: 'qweather' };\n"
L"  }\n"
L"  return { rows: state.fallback && state.fallback.data.hourly || [], provider: 'open-meteo' };\n"
L"}\n"
L"\n"
L"function dailySource() {\n"
L"  if (state.mode === 'qweather') {\n"
L"    return { rows: state.datasets.daily && state.datasets.daily.data || [], provider: 'qweather' };\n"
L"  }\n"
L"  return { rows: state.fallback && state.fallback.data.daily || [], provider: 'open-meteo' };\n"
L"}\n"
L"\n"
L"function hasCurrentData() {\n"
L"  return currentSource() !== null;\n"
L"}\n"
L"\n"
L"function setLoading() {\n"
L"  const value = labels();\n"
L"  setStaticLabels();\n"
L"  document.documentElement.lang = state.language || 'en';\n"
L"  elements.location.textContent = state.location || 'Weather';\n"
L"  elements.resolved.textContent = '';\n"
L"  elements.providerState.textContent = '';\n"
L"  elements.condition.textContent = value.loading;\n"
L"  elements.temperature.textContent = '--';\n"
L"  elements.unit.textContent = tempUnit();\n"
L"  elements.updated.textContent = '';\n"
L"  elements.feels.textContent = '--';\n"
L"  elements.humidity.textContent = '--';\n"
L"  elements.wind.textContent = '--';\n"
L"  elements.precip.textContent = '--';\n"
L"  elements.visibility.textContent = '--';\n"
L"  elements.alerts.hidden = true;\n"
L"  elements.minuteSection.hidden = true;\n"
L"  elements.airSection.hidden = true;\n"
L"  elements.hourly.replaceChildren();\n"
L"  elements.forecast.replaceChildren();\n"
L"  drawWeatherIcon(elements.currentIcon, { code: '999', isDay: 1 }, 'qweather');\n"
L"}\n"
L"\n"
L"function setError() {\n"
L"  setLoading();\n"
L"  elements.condition.textContent = labels().error;\n"
L"  elements.providerState.textContent = state.apiHost ? labels().fallback : 'Open-Meteo';\n"
L"  elements.providerState.classList.add('warning');\n"
L"}\n"
L"\n"
L"function renderProviderState() {\n"
L"  const value = labels();\n"
L"  elements.providerState.classList.remove('warning');\n"
L"  if (state.qAuthFailed) {\n"
L"    elements.providerState.textContent = state.mode === 'qweather'\n"
L"      ? `${value.authFailed} | ${value.lastData}`\n"
L"      : `${value.authFailed} | ${value.fallback}`;\n"
L"    elements.providerState.classList.add('warning');\n"
L"  } else if (state.mode === 'qweather') {\n"
L"    const hasErrors = Object.keys(state.errors).some((name) => name !== 'fallback');\n"
L"    elements.providerState.textContent = hasErrors ? `${value.qweather} | ${value.partial}` : value.qweather;\n"
L"    elements.providerState.classList.toggle('warning', hasErrors);\n"
L"  } else if (state.apiHost) {\n"
L"    elements.providerState.textContent = value.fallback;\n"
L"    elements.providerState.classList.add('warning');\n"
L"  } else {\n"
L"    elements.providerState.textContent = 'Open-Meteo';\n"
L"  }\n"
L"}\n"
L"\n"
L"function alertColor(alert) {\n"
L"  const rawColor = alert.color && typeof alert.color === 'object'\n"
L"    ? textValue(pick(alert.color, ['code', 'name']))\n"
L"    : textValue(alert.color);\n"
L"  const value = `${alert.severity} ${alert.title} ${rawColor}`.toLowerCase();\n"
L"  if (/red|extreme|severe|\\u7ea2|\\u7279\\u522b\\u4e25\\u91cd/.test(value)) return '#b3261e';\n"
L"  if (/orange|moderate|\\u6a59|\\u4e25\\u91cd/.test(value)) return '#c55318';\n"
L"  if (/yellow|minor|\\u9ec4|\\u8f83\\u91cd/.test(value)) return '#9a6500';\n"
L"  if (/blue|\\u84dd|\\u4e00\\u822c/.test(value)) return '#286fa8';\n"
L"  return '#b3261e';\n"
L"}\n"
L"\n"
L"function alertLevelText(alert) {\n"
L"  const rawColor = alert.color && typeof alert.color === 'object'\n"
L"    ? textValue(pick(alert.color, ['code', 'name'])).toLowerCase()\n"
L"    : textValue(alert.color).toLowerCase();\n"
L"  if (isChinese()) {\n"
L"    const colorNames = { red: '\\u7ea2\\u8272', orange: '\\u6a59\\u8272', yellow: '\\u9ec4\\u8272', blue: '\\u84dd\\u8272', white: '\\u767d\\u8272' };\n"
L"    if (colorNames[rawColor]) return colorNames[rawColor];\n"
L"  }\n"
L"  return textValue(alert.severity) || rawColor || labels().officialAlert;\n"
L"}\n"
L"\n"
L"function alertBlock(label, content) {\n"
L"  if (!content) return null;\n"
L"  const block = document.createElement('div');\n"
L"  block.className = 'alert-block';\n"
L"  const heading = document.createElement('strong');\n"
L"  heading.textContent = label;\n"
L"  const text = document.createElement('div');\n"
L"  text.textContent = content;\n"
L"  block.append(heading, text);\n"
L"  return block;\n"
L"}\n"
L"\n"
L"function renderAlerts() {\n"
L"  const value = labels();\n"
L"  const data = state.mode === 'qweather' && state.datasets.alerts && state.datasets.alerts.data;\n"
L"  const alerts = data && Array.isArray(data.items) ? data.items : [];\n"
L"  elements.alerts.replaceChildren();\n"
L"  elements.alerts.hidden = alerts.length === 0;\n"
L"  for (const alert of alerts) {\n"
L"    const details = document.createElement('details');\n"
L"    details.className = 'alert';\n"
L"    details.style.setProperty('--alert-color', alertColor(alert));\n"
L"    const summary = document.createElement('summary');\n"
L"    const level = document.createElement('span');\n"
L"    level.className = 'alert-level';\n"
L"    level.textContent = alertLevelText(alert);\n"
L"    const title = document.createElement('span');\n"
L"    title.className = 'alert-title';\n"
L"    title.textContent = alert.title || alert.type || value.officialAlert;\n"
L"    const time = document.createElement('span');\n"
L"    time.className = 'alert-time';\n"
L"    time.textContent = formatTime(alert.published, true);\n"
L"    summary.append(level, title, time);\n"
L"    const body = document.createElement('div');\n"
L"    body.className = 'alert-body';\n"
L"    const meta = document.createElement('div');\n"
L"    meta.className = 'alert-meta';\n"
L"    const metaParts = [];\n"
L"    if (alert.sender) metaParts.push(`${value.publisher}: ${alert.sender}`);\n"
L"    const period = [formatTime(alert.start, true), formatTime(alert.end, true)].filter(Boolean).join(' - ');\n"
L"    if (period) metaParts.push(`${value.validUntil}: ${period}`);\n"
L"    meta.textContent = metaParts.join(' | ');\n"
L"    if (meta.textContent) body.append(meta);\n"
L"    for (const block of [\n"
L"      alertBlock(value.details, alert.description),\n"
L"      alertBlock(value.standard, alert.standard),\n"
L"      alertBlock(value.instruction, alert.instruction)\n"
L"    ]) if (block) body.append(block);\n"
L"    details.append(summary, body);\n"
L"    details.addEventListener('toggle', notifyHost);\n"
L"    elements.alerts.append(details);\n"
L"  }\n"
L"}\n"
L"\n"
L"function renderMinuteForecast() {\n"
L"  const value = labels();\n"
L"  const minute = state.mode === 'qweather' && state.datasets.minutely && state.datasets.minutely.data;\n"
L"  if (!minute) {\n"
L"    elements.minuteSection.hidden = true;\n"
L"    return;\n"
L"  }\n"
L"  elements.minuteSection.hidden = false;\n"
L"  if (minute.available === false) {\n"
L"    elements.minuteUpdated.textContent = '';\n"
L"    elements.minuteSummary.textContent = value.unavailable;\n"
L"    elements.minuteSummary.style.color = 'var(--muted)';\n"
L"    elements.minuteChart.replaceChildren();\n"
L"    elements.minuteAxis.replaceChildren();\n"
L"    return;\n"
L"  }\n"
L"  elements.minuteUpdated.textContent = [value.minutePoints, formatTime(minute.updated)].filter(Boolean).join(' | ');\n"
L"  const points = Array.isArray(minute.points) ? minute.points.slice(0, 24) : [];\n"
L"  const raining = points.some((point) => Number(point.precip) > 0);\n"
L"  elements.minuteSummary.textContent = minute.summary || (raining ? value.next2h : value.noRain);\n"
L"  elements.minuteSummary.style.color = raining ? 'var(--orange)' : 'var(--text)';\n"
L"  elements.minuteChart.replaceChildren();\n"
L"  const max = Math.max(0.1, ...points.map((point) => Number(point.precip) || 0));\n"
L"  for (let index = 0; index < 24; ++index) {\n"
L"    const point = points[index] || { precip: 0 };\n"
L"    const bar = document.createElement('span');\n"
L"    bar.className = 'minute-bar';\n"
L"    bar.style.height = `${Math.max(2, Math.round((Number(point.precip) || 0) / max * 42))}px`;\n"
L"    bar.title = `${formatTime(point.time)} ${formatNumber(point.precip, ' mm', 1)}`;\n"
L"    elements.minuteChart.append(bar);\n"
L"  }\n"
L"  elements.minuteAxis.replaceChildren();\n"
L"  for (const label of ['0', '30', '60', '90', '120 min']) {\n"
L"    const span = document.createElement('span');\n"
L"    span.textContent = label;\n"
L"    elements.minuteAxis.append(span);\n"
L"  }\n"
L"}\n"
L"\n"
L"function renderHourly() {\n"
L"  const value = labels();\n"
L"  const source = hourlySource();\n"
L"  let rows = Array.isArray(source.rows) ? source.rows : [];\n"
L"  if (source.provider === 'open-meteo') {\n"
L"    const current = currentSource();\n"
L"    const currentTime = current && current.item.time || '';\n"
L"    let start = rows.findIndex((row) => textValue(row.time) >= textValue(currentTime));\n"
L"    if (start < 0) start = 0;\n"
L"    rows = rows.slice(start, start + 24);\n"
L"  } else {\n"
L"    rows = rows.slice(0, 24);\n"
L"  }\n"
L"  elements.hourly.replaceChildren();\n"
L"  elements.hourlyNote.textContent = rows.length ? `${value.rainChance} | ${rows.length}h` : value.unavailable;\n"
L"  for (let index = 0; index < rows.length; ++index) {\n"
L"    const row = rows[index];\n"
L"    const hour = document.createElement('div');\n"
L"    hour.className = 'hour';\n"
L"    const time = document.createElement('div');\n"
L"    time.className = 'hour-time';\n"
L"    time.textContent = index === 0 && source.provider === 'open-meteo' ? value.now : formatTime(row.time);\n"
L"    const icon = document.createElement('canvas');\n"
L"    icon.width = 48; icon.height = 48;\n"
L"    drawWeatherIcon(icon, row, source.provider);\n"
L"    const temperature = document.createElement('div');\n"
L"    temperature.className = 'hour-temp';\n"
L"    temperature.textContent = formatTemperature(row.temp);\n"
L"    const probability = document.createElement('div');\n"
L"    probability.className = 'hour-prob';\n"
L"    probability.textContent = row.pop === null || row.pop === undefined ? '--' : `${row.pop}%`;\n"
L"    probability.title = weatherText(row, source.provider);\n"
L"    hour.append(time, icon, temperature, probability);\n"
L"    elements.hourly.append(hour);\n"
L"  }\n"
L"  if (!rows.length) {\n"
L"    const empty = document.createElement('div');\n"
L"    empty.className = 'empty';\n"
L"    empty.textContent = value.unavailable;\n"
L"    elements.hourly.append(empty);\n"
L"  }\n"
L"}\n"
L"\n"
L"function aqiColor(aqi) {\n"
L"  const value = Number(aqi);\n"
L"  if (value <= 50) return 'var(--green)';\n"
L"  if (value <= 100) return 'var(--amber)';\n"
L"  if (value <= 150) return 'var(--orange)';\n"
L"  return 'var(--red)';\n"
L"}\n"
L"\n"
L"function renderAirQuality() {\n"
L"  const value = labels();\n"
L"  const air = state.mode === 'qweather' && state.datasets.air && state.datasets.air.data;\n"
L"  if (!air) {\n"
L"    elements.airSection.hidden = state.mode !== 'qweather';\n"
L"    elements.airNote.textContent = value.unavailable;\n"
L"    elements.aqiValue.textContent = '--';\n"
L"    elements.aqiCategory.textContent = '';\n"
L"    elements.pollutants.replaceChildren();\n"
L"    elements.airAdvice.textContent = '';\n"
L"    return;\n"
L"  }\n"
L"  elements.airSection.hidden = false;\n"
L"  elements.airNote.textContent = air.primary ? `${isChinese() ? '\\u9996\\u8981\\u6c61\\u67d3\\u7269' : 'Primary'}: ${air.primary}` : '';\n"
L"  elements.aqiValue.textContent = air.aqi === null ? '--' : Math.round(air.aqi);\n"
L"  elements.aqiValue.style.color = aqiColor(air.aqi);\n"
L"  elements.aqiCategory.textContent = [air.category, air.level ? `${isChinese() ? '\\u7b49\\u7ea7' : 'Level'} ${air.level}` : ''].filter(Boolean).join(' | ');\n"
L"  elements.pollutants.replaceChildren();\n"
L"  for (const pollutant of (air.pollutants || []).slice(0, 6)) {\n"
L"    const item = document.createElement('div');\n"
L"    item.className = 'pollutant';\n"
L"    const name = document.createElement('span');\n"
L"    name.className = 'pollutant-name';\n"
L"    name.textContent = pollutant.name || pollutant.code.toUpperCase();\n"
L"    const number = document.createElement('span');\n"
L"    number.className = 'pollutant-value';\n"
L"    number.textContent = formatNumber(pollutant.value, '', pollutant.code === 'co' ? 1 : 0);\n"
L"    number.title = pollutant.unit;\n"
L"    item.append(name, number);\n"
L"    elements.pollutants.append(item);\n"
L"  }\n"
L"  elements.airAdvice.textContent = air.advice || '';\n"
L"}\n"
L"\n"
L"function renderDaily() {\n"
L"  const value = labels();\n"
L"  const source = dailySource();\n"
L"  const rows = Array.isArray(source.rows) ? source.rows.slice(0, 5) : [];\n"
L"  elements.forecast.replaceChildren();\n"
L"  elements.dailyNote.textContent = rows.length ? '' : value.unavailable;\n"
L"  const formatter = new Intl.DateTimeFormat(state.language || 'en-US', { weekday: 'short' });\n"
L"  for (let index = 0; index < rows.length; ++index) {\n"
L"    const row = rows[index];\n"
L"    const day = document.createElement('div');\n"
L"    day.className = 'day';\n"
L"    const name = document.createElement('div');\n"
L"    name.className = 'day-name';\n"
L"    try {\n"
L"      name.textContent = index === 0 ? value.today : formatter.format(new Date(`${row.date}T12:00:00`));\n"
L"    } catch (error) {\n"
L"      name.textContent = row.date;\n"
L"    }\n"
L"    const icon = document.createElement('canvas');\n"
L"    icon.width = 48; icon.height = 48;\n"
L"    drawWeatherIcon(icon, row, source.provider);\n"
L"    const text = document.createElement('div');\n"
L"    text.className = 'day-text';\n"
L"    text.textContent = weatherText(row, source.provider);\n"
L"    const temperature = document.createElement('div');\n"
L"    temperature.className = 'day-temp';\n"
L"    temperature.textContent = `${formatTemperature(row.tempMax)} / ${formatTemperature(row.tempMin)}`;\n"
L"    day.append(name, icon, text, temperature);\n"
L"    elements.forecast.append(day);\n"
L"  }\n"
L"}\n"
L"\n"
L"function collectSources() {\n"
L"  const sources = [];\n"
L"  function append(values) {\n"
L"    for (const value of values || []) {\n"
L"      const clean = textValue(value);\n"
L"      if (clean && !sources.some((existing) => existing.toLowerCase() === clean.toLowerCase())) sources.push(clean);\n"
L"    }\n"
L"  }\n"
L"  if (state.mode === 'qweather') {\n"
L"    append(['QWeather']);\n"
L"    for (const name of DATASET_NAMES) {\n"
L"      const dataset = state.datasets[name];\n"
L"      append(dataset && dataset.refer && dataset.refer.sources);\n"
L"      append(dataset && dataset.data && dataset.data.refer && dataset.data.refer.sources);\n"
L"    }\n"
L"  } else {\n"
L"    append(['Open-Meteo', state.place && state.place.source]);\n"
L"  }\n"
L"  return sources;\n"
L"}\n"
L"\n"
L"function qweatherAttributionUrl() {\n"
L"  for (const name of DATASET_NAMES) {\n"
L"    const links = state.datasets[name] && state.datasets[name].refer && state.datasets[name].refer.attributions;\n"
L"    for (const link of links || []) {\n"
L"      if (/^https:\\/\\/developer\\.qweather\\.com\\/attribution\\.html(?:[?#].*)?$/i.test(link)) return link;\n"
L"    }\n"
L"  }\n"
L"  return 'https://developer.qweather.com/attribution.html';\n"
L"}\n"
L"\n"
L"function renderSources() {\n"
L"  const value = labels();\n"
L"  elements.poweredBy.replaceChildren();\n"
L"  if (state.mode === 'qweather') {\n"
L"    const link = document.createElement('a');\n"
L"    link.href = qweatherAttributionUrl();\n"
L"    link.textContent = value.powered;\n"
L"    elements.poweredBy.append(link);\n"
L"  } else {\n"
L"    const link = document.createElement('a');\n"
L"    link.href = 'https://open-meteo.com/';\n"
L"    link.textContent = 'Open-Meteo';\n"
L"    elements.poweredBy.append(link);\n"
L"  }\n"
L"  const sources = collectSources();\n"
L"  elements.sourceList.textContent = sources.length ? `${value.sources}: ${sources.join(', ')}` : '';\n"
L"}\n"
L"\n"
L"function renderWeather() {\n"
L"  const current = currentSource();\n"
L"  if (!current) {\n"
L"    if (state.status === 'error') setError();\n"
L"    return;\n"
L"  }\n"
L"  const value = labels();\n"
L"  const item = current.item;\n"
L"  document.documentElement.lang = state.language || 'en';\n"
L"  setStaticLabels();\n"
L"  elements.location.textContent = state.place && state.place.name || state.location;\n"
L"  const resolvedParts = [state.place && state.place.city, state.place && state.place.country]\n"
L"    .map((part) => textValue(part))\n"
L"    .filter((part, index, array) => part && array.indexOf(part) === index && part !== elements.location.textContent);\n"
L"  elements.resolved.textContent = resolvedParts.length ? ` | ${resolvedParts.join(' | ')}` : '';\n"
L"  renderProviderState();\n"
L"  elements.temperature.textContent = Math.round(displayTemperatureValue(item.temp));\n"
L"  elements.unit.textContent = tempUnit();\n"
L"  elements.condition.textContent = weatherText(item, current.provider);\n"
L"  const updateTime = item.time || current.fetchedAt;\n"
L"  elements.updated.textContent = updateTime ? `${value.updated} ${formatTime(updateTime)}` : '';\n"
L"  elements.feels.textContent = formatTemperature(item.feels);\n"
L"  elements.humidity.textContent = formatNumber(item.humidity, '%');\n"
L"  const windSpeed = item.windSpeed === null || item.windSpeed === undefined\n"
L"    ? null\n"
L"    : state.unit ? Number(item.windSpeed) / 1.609344 : Number(item.windSpeed);\n"
L"  const precipitation = item.precip === null || item.precip === undefined\n"
L"    ? null\n"
L"    : state.unit ? Number(item.precip) / 25.4 : Number(item.precip);\n"
L"  const visibility = item.visibility === null || item.visibility === undefined\n"
L"    ? null\n"
L"    : state.unit ? Number(item.visibility) / 1.609344 : Number(item.visibility);\n"
L"  elements.wind.textContent = `${item.windDir ? `${formatWindDirection(item.windDir)} ` : ''}${formatNumber(windSpeed, state.unit ? ' mph' : ' km/h')}`;\n"
L"  elements.precip.textContent = formatNumber(precipitation, state.unit ? ' in' : ' mm', state.unit ? 2 : 1);\n"
L"  elements.visibility.textContent = formatNumber(visibility, state.unit ? ' mi' : ' km', 0);\n"
L"  drawWeatherIcon(elements.currentIcon, item, current.provider);\n"
L"  renderAlerts();\n"
L"  renderMinuteForecast();\n"
L"  renderHourly();\n"
L"  renderAirQuality();\n"
L"  renderDaily();\n"
L"  renderSources();\n"
L"}\n"
L"\n"
L"function scheduleRenderAndCapture(captureTaskbar) {\n"
L"  if (renderTimer) clearTimeout(renderTimer);\n"
L"  renderTimer = setTimeout(() => {\n"
L"    renderTimer = null;\n"
L"    renderWeather();\n"
L"    if (captureTaskbar || hasCurrentData()) notifyHost();\n"
L"  }, 0);\n"
L"}\n"
L"\n"
L"function notifyHost() {\n"
L"  if (state.notifyTimer) clearTimeout(state.notifyTimer);\n"
L"  state.notifyTimer = setTimeout(() => {\n"
L"    state.notifyTimer = null;\n"
L"    try {\n"
L"      if (window.chrome && window.chrome.webview) window.chrome.webview.postMessage('ep_weather_updated');\n"
L"    } catch (error) {\n"
L"      // The standalone verifier and visual tests do not provide a WebView host.\n"
L"    }\n"
L"  }, 300);\n"
L"}\n"
L"\n"
L"function imageHex(width, height) {\n"
L"  const outputWidth = Math.max(1, Math.min(64, Number(width) || 32));\n"
L"  const outputHeight = Math.max(1, Math.min(64, Number(height) || outputWidth));\n"
L"  const source = elements.currentIcon;\n"
L"  const sourceContext = source.getContext('2d');\n"
L"  const pixels = sourceContext.getImageData(0, 0, source.width, source.height).data;\n"
L"  let left = source.width, top = source.height, right = -1, bottom = -1;\n"
L"  for (let y = 0; y < source.height; ++y) {\n"
L"    for (let x = 0; x < source.width; ++x) {\n"
L"      if (pixels[(y * source.width + x) * 4 + 3] > 8) {\n"
L"        left = Math.min(left, x); top = Math.min(top, y);\n"
L"        right = Math.max(right, x); bottom = Math.max(bottom, y);\n"
L"      }\n"
L"    }\n"
L"  }\n"
L"  const canvas = document.createElement('canvas');\n"
L"  canvas.width = outputWidth; canvas.height = outputHeight;\n"
L"  const context = canvas.getContext('2d');\n"
L"  if (right >= left && bottom >= top) {\n"
L"    const padding = 2;\n"
L"    left = Math.max(0, left - padding); top = Math.max(0, top - padding);\n"
L"    right = Math.min(source.width - 1, right + padding); bottom = Math.min(source.height - 1, bottom + padding);\n"
L"    const sourceWidth = right - left + 1;\n"
L"    const sourceHeight = bottom - top + 1;\n"
L"    const scale = Math.min((outputWidth - 2) / sourceWidth, (outputHeight - 2) / sourceHeight);\n"
L"    const destinationWidth = Math.max(1, Math.round(sourceWidth * scale));\n"
L"    const destinationHeight = Math.max(1, Math.round(sourceHeight * scale));\n"
L"    context.drawImage(source, left, top, sourceWidth, sourceHeight,\n"
L"      Math.floor((outputWidth - destinationWidth) / 2), Math.floor((outputHeight - destinationHeight) / 2),\n"
L"      destinationWidth, destinationHeight);\n"
L"  }\n"
L"  const output = context.getImageData(0, 0, outputWidth, outputHeight).data;\n"
L"  const digits = '0123456789abcdef';\n"
L"  let result = '';\n"
L"  for (let index = 0; index < output.length; index += 4) {\n"
L"    const alpha = output[index + 3];\n"
L"    const values = [\n"
L"      Math.round(output[index + 2] * alpha / 255),\n"
L"      Math.round(output[index + 1] * alpha / 255),\n"
L"      Math.round(output[index] * alpha / 255),\n"
L"      alpha\n"
L"    ];\n"
L"    for (const value of values) result += digits[(value >> 4) & 15] + digits[value & 15];\n"
L"  }\n"
L"  return result;\n"
L"}\n"
L"\n"
L"function contentHeight() {\n"
L"  const availableHeight = Number(window.screen && window.screen.availHeight) || 900;\n"
L"  const maximumHeight = Math.max(480, Math.min(820, availableHeight - 80));\n"
L"  const height = Math.min(elements.weather.scrollHeight, maximumHeight);\n"
L"  return Math.max(367, Math.ceil(height * 367 / 353));\n"
L"}\n"
L"\n"
L"function safeField(value) {\n"
L"  return textValue(value).replace(/[#\"]/g, ' ');\n"
L"}\n"
L"\n"
L"window.epWeatherGetData = function(location, language, unit, width, height, apiHost) {\n"
L"  const cleanLocation = textValue(location);\n"
L"  const cleanLanguage = textValue(language, 'en-US') || 'en-US';\n"
L"  const selectedUnit = Number(unit) ? 1 : 0;\n"
L"  const cleanHost = validQWeatherHost(apiHost) ? textValue(apiHost).toLowerCase() : '';\n"
L"  const key = `${cleanLocation}\\n${cleanLanguage}\\n${selectedUnit}\\n${cleanHost}`;\n"
L"  state.iconWidth = width;\n"
L"  state.iconHeight = height;\n"
L"  if (state.key !== key) {\n"
L"    state.key = key;\n"
L"    state.location = cleanLocation;\n"
L"    state.language = cleanLanguage;\n"
L"    state.unit = selectedUnit;\n"
L"    state.apiHost = cleanHost;\n"
L"    resetState();\n"
L"    initializeWeather(state.generation);\n"
L"    return 'ep_pending';\n"
L"  }\n"
L"  refreshDue(false).catch(() => {});\n"
L"  if (state.status === 'loading' || state.status === 'idle') return 'ep_pending';\n"
L"  const current = currentSource();\n"
L"  if (state.status !== 'ready' || !current) return 'ep_error';\n"
L"  const item = current.item;\n"
L"  return `${document.documentElement.getAttribute('dir') || 'ltr'}#${contentHeight()}#${Math.round(displayTemperatureValue(item.temp))}#${tempUnit()}#${safeField(weatherText(item, current.provider))}#${safeField(state.place && state.place.name || state.location)}#${imageHex(width, height)}`;\n"
L"};\n"
L"\n"
L"if (window.__epWeatherTestMode) {\n"
L"  window.__epWeatherTest = Object.freeze({\n"
L"    state,\n"
L"    normalizeQCurrent,\n"
L"    normalizeQHourly,\n"
L"    normalizeQDaily,\n"
L"    normalizeQMinutely,\n"
L"    normalizeQAlerts,\n"
L"    normalizeQAir,\n"
L"    normalizeOpenMeteo,\n"
L"    validQWeatherHost,\n"
L"    refreshDue,\n"
L"    DATASET_TTL,\n"
L"    renderWeather,\n"
L"    contentHeight\n"
L"  });\n"
L"}\n"
L"\n"
L"setLoading();\n"
L"})();\n"
L"</script>\n"
L"</body>\n"
L"</html>\n"
;
